CREATE TABLE IF NOT EXISTS stock_transfers (id INT AUTO_INCREMENT PRIMARY KEY, tenant_id INT NOT NULL, from_store_id INT NOT NULL, to_store_id INT NOT NULL, status ENUM('pending', 'in_transit', 'received', 'cancelled') DEFAULT 'pending', transfer_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP, received_at TIMESTAMP NULL, created_by INT, notes TEXT, FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE, FOREIGN KEY (from_store_id) REFERENCES stores(id), FOREIGN KEY (to_store_id) REFERENCES stores(id), FOREIGN KEY (created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
